package com.zungun.runtime.link

import org.junit.Assert.assertEquals
import org.junit.Test

class LinkPlannerGoldenTest {
    @Test fun sharedTypeScriptKotlinCorpusMatchesExactly(){val stream=requireNotNull(javaClass.classLoader?.getResourceAsStream("link-planner-v1.vectors")){"LINK_VECTOR_CORPUS_MISSING"};val lines=stream.bufferedReader().use{it.readLines()}.filter{it.isNotBlank()}.drop(1);assertEquals(10,lines.size);for(line in lines){val parts=line.split('|');require(parts.size==41){"LINK_VECTOR_COLUMN_COUNT:${parts.size}"};val plan=LinkPlanner.create(row(parts));val actual=listOf(plan.decision.name,plan.reasonCodes.joinToString("+"),plan.plannedBytes.toString(),plan.profileHash,plan.snapshotHash,plan.planId);assertEquals(parts[0],parts.subList(35,41),actual)}}
    private fun row(parts:List<String>):LinkPlannerInput{fun s(i:Int)=parts[i];fun nullable(value:String):String?=if(value=="~")null else value;fun n(i:Int)=nullable(s(i))?.toLong();fun bool(i:Int)=s(i)=="true";val profile=DeliveryProfileV2(urgency=LinkUrgency.valueOf(s(2)),deadlineAtMs=n(3),expiresAtMs=n(4),maxDelayMs=n(5),retryContract=LinkRetryContract.valueOf(s(6)),idempotencyRequired=bool(7),semanticRevalidationRequired=true,orderingKey=null,dependencies=emptyList(),payloadStrategy=LinkPayloadStrategy.valueOf(s(8)),maxImmediateBytes=s(9).toInt(),allowMetered=bool(10),allowRoaming=bool(11),allowCongested=bool(12),allowUnvalidated=bool(13),heavyDataPolicy="DEFER_ON_CONSTRAINED",activeProbeBudgetBytes=0,transportAllowlist=listOf("http"),receiptRequirement="DURABLE_ACCEPTANCE",evidenceRequirement="FULL_WITNESS");val snapshot=LinkSnapshot("s1",s(14).toLong(),s(15).toLong(),bool(16),bool(17),bool(18),bool(19),bool(20),bool(21),bool(22),bool(23),false,bool(24),1000,500,listOf("CELLULAR"),"net:1",100,0,500);val payload=LinkPayloadShape(s(25).toInt(),nullable(s(26))?.toInt(),s(27).toInt(),nullable(s(28))?.toInt(),nullable(s(29)),nullable(s(30)),s(27).toInt()>0);return LinkPlannerInput(nowMs=s(1).toLong(),opId="op1",profile=profile,snapshot=snapshot,payload=payload,transports=listOf(LinkTransportCapability("http",true,null,true)),priorAmbiguousOutcome=bool(31),automaticRetryAttempt=bool(32),activeProbeBytesUsed=0,hasOutstandingDeferredObjects=bool(33),prefetchEligible=bool(34))}
}
